import sys
import jax.numpy as jnp
sys.path.append('storage/episteme')
from episteme_sota_v2 import FactorizedMLP_with_RC_LN

# New component: custom loss function
def compute_loss(predictions, targets, params, x):
    mae = jnp.mean(jnp.abs(predictions - targets))
    # NEW: Penalize the first derivative (y_t - y_{t-1})^2
    first_deriv_sq = (predictions[:, 1:, :] - predictions[:, :-1, :])**2
    curv_pen = jnp.mean(first_deriv_sq)
    return mae + 1e-4 * curv_pen # Keep lambda the same for a direct comparison

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'rank_k': 320,
        'proj_rank': 32,
    }

class ModelWrapper:
    def __init__(self, hparams):
        self.model = FactorizedMLP_with_RC_LN(
            rank_k=hparams['rank_k'],
            proj_rank=hparams['proj_rank']
        )
        self.needs_rng = True

    def init(self, rng_key, dummy_input):
        return self.model.init({'params': rng_key, 'dropout': rng_key}, dummy_input)

    def apply(self, params, x, training=False, rngs=None):
        return self.model.apply(params, x, training=training, rngs=rngs)

def create_network(hparams):
    return ModelWrapper(hparams)
